:root {
  color-scheme: dark;

  /* — Superficies: escalera de luminancia, hue frío fijo 255, croma mínimo — */
  --bg-0: oklch(0.145 0.012 255);   /* raíz / vacío */
  --bg-1: oklch(0.175 0.014 255);   /* paneles */
  --bg-2: oklch(0.215 0.016 255);   /* paneles elevados */
  --bg-3: oklch(0.26  0.018 255);   /* inputs, hover */

  /* — Texto: 4 niveles; los 4 pasan AA normal sobre --bg-1 (medido) — */
  --text-hi:   oklch(0.955 0.01 250);  /*  8.7:1  titulares */
  --text-body: oklch(0.88  0.02 250);  /*  7.9:1  cuerpo    */
  --text-mute: oklch(0.72  0.02 255);  /*  6.1:1  etiquetas */
  --text-hint: oklch(0.60  0.02 255);  /*  4.8:1  hint      */

  /* — Acento cian: 3 pasos + translúcido para glow/fondos — */
  --accent-400: oklch(0.78 0.16 220);  /* 6.1:1 — texto/hover acentuado */
  --accent-500: oklch(0.72 0.175 225); /* 5.6:1 — primario, AA en texto */
  --accent-600: oklch(0.62 0.165 230); /* fondo del botón primario */
  --accent-glow: oklch(0.72 0.175 225 / 0.25);
  --ok: oklch(0.78 0.16 155);  /* 6.6:1 */
  --warn: oklch(0.80 0.16 85); /* 6.7:1 */
  --danger: oklch(0.68 0.19 25); /* 4.8:1 — AA normal al límite */

  /* — Hairlines: bordes derivados del propio fondo (nunca gris plano) — */
  --hairline:        color-mix(in oklab, var(--bg-1), white 14%); /* ~2.0:1 decorativo */
  --hairline-strong: color-mix(in oklab, var(--bg-1), white 24%); /* ~2.7:1 */

  /* — Espaciado 4pt FIJO: no escala con la ventana — */
  --sp-1: .25rem; --sp-2: .5rem; --sp-3: 1rem; --sp-4: 1.5rem; --sp-6: 3rem;

  /* — Radios duales: técnico para controles, suave para paneles — */
  --r-tech: 3px; --r-sm: 6px; --r-md: 10px; --r-lg: 16px;

  /* — Tipografía fluida: ratio 1.3, interpolada entre 900 y 2560 px
     (el ancho real de la ventana del webview; ver técnica de clamp) — */
  --step--2: clamp(0.6875rem, 0.6028rem + 0.1506vw, 0.8438rem);
  --step--1: clamp(0.8125rem, 0.7278rem + 0.1506vw, 0.9688rem);
  --step-0:  clamp(0.9375rem, 0.8697rem + 0.1205vw, 1.0625rem);
  --step-1:  clamp(1.1875rem, 1.0858rem + 0.1807vw, 1.375rem);
  --step-2:  clamp(1.4688rem, 1.2993rem + 0.3012vw, 1.7812rem);
  --step-3:  clamp(1.8125rem, 1.5584rem + 0.4518vw, 2.2812rem);
  --lh-tight: 1.18; --lh-body: 1.55;

  /* — Motion — */
  --t-fast: 120ms; --t-base: 200ms; --t-slow: 480ms;
  --ease-out: cubic-bezier(0.2, 0, 0, 1);
  --ease-spring: cubic-bezier(.34, 1.56, .64, 1);

  /* — Fuentes con fallbacks de sistema — */
  --font-ui: "IBM Plex Sans", system-ui, -apple-system, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, "Cascadia Mono", Menlo, Consolas, monospace;
  --font-display: "Chakra Petch", var(--font-ui);
}

/* Reglas codificadas: los 4 textos pasan 4.5:1 sobre --bg-1 (medido);
   accent-500 (5.6:1) sirve como color de TEXTO; los hairlines NO comunican estado. */

/* Bordes/focus que comunican estado (1.4.11, ≥3:1) → acento o semánticos: */
.control[aria-invalid="true"] { border-color: var(--danger); }   /* 4.8:1 ✓ */
:focus-visible { outline: 2px solid var(--accent-400); outline-offset: 2px; } /* 6.1:1 ✓ */

/* Botón primario: texto oscuro sobre accent-600 → 5.7:1 (medido) ✓ */
.button-primary { color: oklch(0.15 0.02 255); }

/* Progressive (WebKitGTK 2.50+ / Safari 26): el motor elige el color de texto */
@supports (color: contrast-color(oklch(0.62 0.165 230))) {
  .button-primary { color: contrast-color(var(--accent-600)); }
}

:root {
  --e-1: 0 1px 2px oklch(0 0 0 / .3);
  --e-2: 0 8px 24px -8px oklch(0 0 0 / .55), inset 0 1px 0 oklch(1 0 0 / .05);
  --e-3: 0 24px 56px -12px oklch(0 0 0 / .6), inset 0 1px 0 oklch(1 0 0 / .05);
}
.panel {
  background: var(--bg-1);
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
}
.panel--raised { background: var(--bg-2); box-shadow: var(--e-2); }
.panel--active { /* el activo sube un paso y toma acento; cero blur, cero deco */
  background: var(--bg-2);
  border-color: var(--accent-500);
  box-shadow: inset 0 1px 0 oklch(1 0 0 / .06),
              0 0 0 1px color-mix(in oklab, var(--accent-500) 30%, transparent);
}

.app { background: var(--hairline); gap: 1px; }   /* el gap pinta la separación */
.app > * { background: var(--bg-0); min-width: 0; min-height: 0; }

/* Variante utilitaria para rejillas interiores */
.grid-h {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 1px;
  background: var(--hairline);
}
.grid-h > * { background: var(--bg-1); padding: var(--sp-3); }

/* Alternativa para UNA sola separación sin cambio de layout: box-shadow */
.hairline-1 { box-shadow: 0 0 0 1px var(--hairline); }

html, body { block-size: 100%; }
.app {
  block-size: 100%;
  display: grid;
  gap: 1px;
  background: var(--hairline);
  grid-template-columns: 248px minmax(0, 1.2fr) minmax(340px, 380px);
  grid-template-rows: minmax(0, 1fr);
  grid-template-areas: "side canvas panel";   /* DISPOSICIÓN 1 */
}
.side   { grid-area: side; display: flex; flex-direction: column; gap: var(--sp-2); padding: var(--sp-2); }
.canvas { grid-area: canvas; overflow: auto; }
.panel  { grid-area: panel;  overflow: auto; }

/* ——— DISPOSICIÓN 2: rail de iconos + canvas↑ / panel↓ ——— */
@media (max-width: 1360px) {
  .app {
    grid-template-columns: 64px minmax(0, 1fr);
    grid-template-rows: minmax(0, 55%) minmax(0, 1fr);
    grid-template-areas: "side canvas" "side panel";
  }
  .side .side-label { display: none; }
  .side-item { position: relative; }
  .side-item::after {  /* tooltip del rail, pinta FUERA de la columna */
    content: attr(data-name);
    position: absolute; inset-inline-start: calc(100% + 10px); inset-block-start: 50%;
    translate: 0 -50%;
    background: var(--bg-3); border: 1px solid var(--hairline-strong);
    padding: 4px 8px; border-radius: var(--r-tech); white-space: nowrap;
    font: 500 11px/1 var(--font-mono); letter-spacing: .06em; color: var(--text-hi);
    opacity: 0; pointer-events: none;
    transition: opacity var(--t-fast) var(--ease-out);
    z-index: 10;
  }
  .side-item:hover::after, .side-item:focus-visible::after { opacity: 1; }
}

/* ——— DISPOSICIÓN 3: columna única con topbar ——— */
@media (max-width: 820px) {
  .app {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(300px, 52vh) minmax(0, 1fr);
    grid-template-areas: "side" "canvas" "panel";
  }
  .side { flex-direction: row; overflow-x: auto; }
}

.device-pane {
  container-type: inline-size;   /* el wrapper se vuelve contenedor de query */
  container-name: device;
}
.device-stage { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--sp-4); }

@container device (min-width: 620px) {
  .device-stage { grid-template-columns: minmax(180px, 38%) minmax(0, 1fr); align-items: center; }
}
@container device (max-width: 460px) {
  .device-readouts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@container device (max-width: 300px) {
  .device-readouts { grid-template-columns: minmax(0, 1fr); }
}

/* El dispositivo escala con el CONTENEDOR: 1cqi = 1% del ancho del hueco */
.device-svg { inline-size: 100%; max-inline-size: 42cqi; margin-inline: auto; }

.profiles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 190px), 1fr));
  gap: var(--sp-3);
}
/* A 900px de ventana: 3-4 columnas; a 2560px: tantas como quepan;
   con 1 sola tarjeta: ocupa la fila completa (auto-fit colapsa las pistas libres). */

/* steps ya calculados (ver :root). Uso: */
.title { font: 600 var(--step-2)/var(--lh-tight) var(--font-display); letter-spacing: .01em; }
.kpi   { font: 500 var(--step-1)/1.2 var(--font-mono); font-variant-numeric: tabular-nums; }
.body-t{ font: 400 var(--step-0)/var(--lh-body) var(--font-ui); }
.hud-label {
  font: 600 11px/1 var(--font-mono);
  text-transform: uppercase;
  letter-spacing: .09em;
  color: var(--text-mute);
}
.footer { font: 500 var(--step--1)/1.4 var(--font-mono); color: var(--text-hint); }

svg.device { inline-size: 100%; block-size: auto; }
.zone { cursor: pointer; outline: none; }
.zone .hit  { fill: none; stroke: transparent; stroke-width: 18; pointer-events: all; }
.zone .fill {
  fill: var(--zi, var(--bg-2));            /* --zi: color de iluminación de la zona */
  transition: fill 180ms var(--ease-out), filter 240ms var(--ease-out);
}
.zone .line {
  fill: none; stroke: var(--hairline-strong); stroke-width: 1.5;
  vector-effect: non-scaling-stroke;        /* hairline de 1.5px a 900px y a 4K */
}
.zone:hover .line, .zone:focus-visible .line { stroke: var(--accent-400); }
.zone:focus-visible .line { stroke-dasharray: 5 4; }
.zone[aria-pressed="true"] .fill { filter: drop-shadow(0 0 14px var(--accent-glow)); }
/* La tira inferior es una LÍNEA, no un shape: su .fill se dibuja con stroke */
.zone[data-zone="strip"] .fill {
  fill: none; stroke: var(--zi, var(--accent-500));
  stroke-width: 3; stroke-linecap: round;
}
@media (prefers-reduced-motion: no-preference) {
  .zone[aria-pressed="true"] .fill { animation: zone-breathe 2.6s var(--ease-out) infinite alternate; }
}
@keyframes zone-breathe {
  from { filter: drop-shadow(0 0 4px var(--accent-glow)); }
  to   { filter: drop-shadow(0 0 16px var(--accent-glow)); }
}

.device-frame { display: grid; place-items: center; min-block-size: 240px; }
svg.device {
  inline-size: 100%;
  max-inline-size: 48cqi;      /* en el hueco del canvas; si no hay container: min(100%, 420px) */
  max-block-size: 58vh;        /* en ventana baja (600px) no roba todo el lienzo */
  height: auto;
}
/* En el markup: <svg class="device" viewBox="0 0 340 440" preserveAspectRatio="xMidYMid meet"> */
/* Y en cada .line: vector-effect: non-scaling-stroke (ver técnica del diagrama). */

.dpi-slider {
  -webkit-appearance: none; appearance: none;
  inline-size: 100%; block-size: 34px;
  background: transparent; margin: 0;
}
.dpi-slider::-webkit-slider-runnable-track {
  block-size: 6px; border-radius: 3px;
  /* 3 capas: relleno hasta --pos (JS) · ticks cada 100%/9 · base */
  background:
    linear-gradient(var(--accent-500) 0 0) left / var(--pos, 0%) 100% no-repeat,
    repeating-linear-gradient(90deg,
      var(--hairline-strong) 0 1px, transparent 1px, transparent calc(100% / 9))
      center / calc(100% - 2px) 13px no-repeat,
    linear-gradient(var(--bg-3) 0 0) center / 100% 6px no-repeat;
}
.dpi-slider::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none;
  inline-size: 18px; block-size: 18px;
  margin-block-start: -6px;   /* quirk WebKit: (6-18)/2: centra el thumb en el track */
  border-radius: 4px;
  background: linear-gradient(var(--text-hi) 0 0) center / 8px 2px no-repeat, var(--accent-400);
  box-shadow: 0 0 0 1px var(--hairline-strong), 0 0 12px var(--accent-glow);
  transition: scale var(--t-fast) var(--ease-out), box-shadow var(--t-fast) var(--ease-out);
}
.dpi-slider:hover::-webkit-slider-thumb  { scale: 1.1; }
.dpi-slider:active::-webkit-slider-thumb { scale: .95; }
.dpi-slider:focus-visible { outline: 2px solid var(--accent-400); outline-offset: 4px; }

.stages { display: grid; gap: 6px; }
.stage {
  display: grid; grid-template-columns: 10px minmax(0, 1fr) minmax(0, 2fr) auto;
  align-items: center; gap: 10px;
  padding: 7px 10px;
  border: 1px solid var(--hairline); border-radius: var(--r-sm);
  background: var(--bg-2);
  position: relative;
  transition: border-color var(--t-fast) var(--ease-out), background var(--t-base) var(--ease-out);
}
.stage > input[type="radio"] { position: absolute; opacity: 0; pointer-events: none; }
.stage:hover { border-color: var(--hairline-strong); }
.stage:has(input:checked) {
  border-color: var(--accent-500);
  background: color-mix(in oklab, var(--accent-500) 7%, var(--bg-2));
  box-shadow: inset 3px 0 0 var(--accent-500);   /* barra activa al borde izquierdo */
}
.stage:has(input:focus-visible) { outline: 2px solid var(--accent-400); outline-offset: 2px; }
.stage .dot { inline-size: 10px; block-size: 10px; border-radius: 2px; background: var(--st, var(--accent-500)); }
.stage input[type="number"] {
  font: 500 var(--step-0)/1 var(--font-mono); font-variant-numeric: tabular-nums;
  background: var(--bg-3); border: 1px solid var(--hairline);
  border-radius: var(--r-tech); color: var(--text-hi);
  padding: 6px 8px; inline-size: 8ch; text-align: right;
}
.stage input[type="number"]::-webkit-outer-spin-button,
.stage input[type="number"]::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }

.macro {
  display: grid; gap: 1px;
  background: var(--hairline);
  border: 1px solid var(--hairline); border-radius: var(--r-md);
  overflow: clip;   /* contén la animación de entrada dentro de las esquinas */
}
.macro {
  counter-reset: ev;   /* el contador vive en el contenedor */
}
.macro-row {
  counter-increment: ev;
  display: grid; align-items: center;
  grid-template-columns: 2.5ch 11ch minmax(0, 1fr) 7ch auto;
  gap: 10px; padding: 8px 12px; background: var(--bg-1);
  font: 500 var(--step--1)/1.4 var(--font-mono);
  transition: opacity var(--t-fast) var(--ease-out), translate var(--t-fast) var(--ease-out);
}
@starting-style { .macro-row { opacity: 0; translate: 0 5px; } }  /* entrada animada (2.46+) */
.macro-row:focus-within { background: var(--bg-2); }
.macro-row .ev-idx::before { content: counter(ev, decimal-leading-zero); color: var(--text-hint); }
.macro-row .ev-ms { font-variant-numeric: tabular-nums; text-align: right; inline-size: 7ch; }
.macro-row .ev-tipo { text-transform: uppercase; letter-spacing: .06em; color: var(--text-mute); }
.macro-rec { color: var(--danger); font-weight: 700; letter-spacing: .08em; }
.macro-total { font: 500 var(--step--1)/1 var(--font-mono); font-variant-numeric: tabular-nums; color: var(--text-mute); }

.color-input {
  -webkit-appearance: none; appearance: none;
  inline-size: 52px; block-size: 34px; padding: 3px;
  border: 1px solid var(--hairline-strong); border-radius: var(--r-sm);
  background: var(--bg-2); cursor: pointer;
}
.color-input::-webkit-color-swatch-wrapper { padding: 0; }
.color-input::-webkit-color-swatch { border: none; border-radius: 3px; }

.swatch {
  inline-size: 22px; block-size: 22px; border-radius: 4px;
  border: 1px solid oklch(1 0 0 / .18); cursor: pointer;
  transition: scale var(--t-fast) var(--ease-spring), box-shadow var(--t-fast) var(--ease-out);
}
.swatch[aria-pressed="true"] { scale: 1.15; box-shadow: 0 0 0 2px var(--bg-0), 0 0 0 4px var(--accent-400); }

.seg { display: inline-flex; background: var(--bg-2); border: 1px solid var(--hairline-strong); border-radius: var(--r-sm); }
.seg label {
  position: relative; padding: 7px 14px; cursor: pointer;
  font: 500 var(--step--1)/1 var(--font-mono); letter-spacing: .04em;
  color: var(--text-mute); border-inline-start: 1px solid var(--hairline);
}
.seg label:first-child { border-inline-start: none; }
.seg input { position: absolute; inset: 0; opacity: 0; cursor: pointer; }
.seg label:has(:checked) {
  background: color-mix(in oklab, var(--accent-500) 16%, transparent);
  color: var(--accent-400);
}
.seg label:has(input:focus-visible) { outline: 2px solid var(--accent-400); outline-offset: -2px; }

.profiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 190px), 1fr)); gap: var(--sp-3); }
.profile {
  position: relative; display: grid; gap: 4px;
  padding: var(--sp-3);
  border: 1px solid var(--hairline); border-radius: var(--r-md);
  background: var(--bg-1); cursor: pointer;
  transition: border-color var(--t-fast) var(--ease-out), background var(--t-base) var(--ease-out);
}
.profile > input[type="radio"] { position: absolute; opacity: 0; pointer-events: none; }
.profile:hover { border-color: var(--hairline-strong); }
.profile:has(input:checked) {
  border-color: var(--accent-500);
  background: color-mix(in oklab, var(--accent-500) 6%, var(--bg-1));
  box-shadow: inset 3px 0 0 var(--accent-500), 0 0 20px -8px var(--accent-glow);
}
.profile:has(input:focus-visible) { outline: 2px solid var(--accent-400); outline-offset: 2px; }
.profile .led { inline-size: 8px; block-size: 8px; border-radius: 50%; background: var(--text-hint); }
.profile:has(input:checked) .led { background: var(--accent-400); box-shadow: 0 0 8px var(--accent-glow); }

/* ——— Batería ——— */
.battery { display: inline-flex; align-items: center; gap: 8px; }
.battery-shell {
  position: relative; inline-size: 44px; block-size: 20px;
  border: 1px solid var(--hairline-strong); border-radius: 3px; padding: 2px;
}
.battery-shell::after {  /* polo */
  content: ""; position: absolute; inset-inline-end: -4px; inset-block: 6px;
  inline-size: 2px; border-radius: 1px; background: var(--hairline-strong);
}
.battery-fill {
  block-size: 100%; border-radius: 1.5px;
  inline-size: var(--lvl, 0%);   /* JS escribe "73%" */
  background: linear-gradient(90deg,
    color-mix(in oklab, var(--accent-500), black 12%), var(--accent-500));
  transition: inline-size 300ms var(--ease-out), background 300ms var(--ease-out);
}
.battery[data-kind="warn"] .battery-fill { background: var(--warn); }
.battery[data-kind="crit"] .battery-fill { background: var(--danger); }
.battery-value {
  font: 500 var(--step--1)/1 var(--font-mono);
  font-variant-numeric: tabular-nums; color: var(--text-body);
}

.toast-region {
  position: fixed; inset-block-end: 14px; inset-inline-end: 14px;
  display: grid; gap: 8px; z-index: 60; pointer-events: none;
}
.toast {
  pointer-events: auto; display: grid; grid-template-columns: 8px 1fr;
  gap: 10px; align-items: center; max-inline-size: 320px;
  padding: 10px 14px;
  border: 1px solid var(--hairline-strong);
  border-inline-start: 3px solid var(--accent-500);
  border-radius: var(--r-md); background: var(--bg-2); box-shadow: var(--e-3);
  animation: toast-in 220ms var(--ease-out);
}
.toast[data-kind="ok"]   { border-inline-start-color: var(--ok); }
.toast[data-kind="warn"] { border-inline-start-color: var(--warn); }
.toast[data-kind="err"]  { border-inline-start-color: var(--danger); }
.toast-dot { inline-size: 8px; block-size: 8px; border-radius: 50%; background: var(--accent-500); }
.toast[data-kind="err"] .toast-dot { background: var(--danger); }
.toast.leaving { animation: toast-out 160ms var(--ease-out) forwards; }
@keyframes toast-in  { from { opacity: 0; translate: 0 8px; } }
@keyframes toast-out { to   { opacity: 0; translate: 0 6px; } }

/* ——— Botón de aplicar ——— */
.action {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  min-inline-size: 132px; padding: 8px 16px;   /* ancho CONSTANTE: sin reflow al cambiar texto */
  border: 1px solid var(--accent-500); border-radius: var(--r-sm);
  background: var(--accent-600); color: oklch(0.15 0.02 255);   /* 5.7:1 AA */
  font: 600 var(--step-0)/1.2 var(--font-ui);
  transition: box-shadow var(--t-base) var(--ease-out), translate var(--t-fast) var(--ease-out);
}
.action:hover  { box-shadow: 0 0 18px var(--accent-glow); }
.action:active { translate: 0 1px; }
.action[data-state="saving"] { pointer-events: none; opacity: .92; }
.action .spin {
  inline-size: 12px; block-size: 12px; border-radius: 50%;
  border: 2px solid oklch(0.15 0.02 255 / .35); border-block-start-color: oklch(0.15 0.02 255);
  animation: spin .7s linear infinite;
}
@keyframes spin { to { rotate: 1turn; } }
.action.flash-ok { animation: flash-ok 650ms var(--ease-out) 1; }
@keyframes flash-ok {
  from { box-shadow: 0 0 0 0 oklch(0.78 0.16 155 / .55); }
  to   { box-shadow: 0 0 0 14px transparent; }
}

/* Esquinas técnicas (2 pseudo-elementos = 4 esquinas vía rotate:180deg) */
.hud-corner { position: relative; }
.hud-corner::before, .hud-corner::after {
  content: ""; position: absolute;
  inline-size: 12px; block-size: 12px;
  border-block-start: 1px solid var(--accent-500);
  border-inline-start: 1px solid var(--accent-500);
  opacity: .55; pointer-events: none;
  transition: opacity var(--t-base) var(--ease-out);
}
.hud-corner::before { inset-block-start: 5px; inset-inline-start: 5px; }
.hud-corner::after { inset-block-end: 5px; inset-inline-end: 5px; rotate: 180deg; }
.hud-corner:has(:focus-visible)::before,
.hud-corner:has(:focus-visible)::after { opacity: 1; }

/* Retícula sutil: 1px de línea, alfa 0.022, celda 24px */
.hud-grid {
  background:
    linear-gradient(oklch(1 0 0 / .022) 1px, transparent 1px),
    linear-gradient(90deg, oklch(1 0 0 / .022) 1px, transparent 1px);
  background-size: 24px 24px;
}

/* Etiqueta de instrumento + dato alineado a la derecha */
.hud-row { display: flex; justify-content: space-between; align-items: baseline; gap: var(--sp-3); }
.hud-label { font: 600 11px/1 var(--font-mono); text-transform: uppercase; letter-spacing: .09em; color: var(--text-mute); }
.hud-value { font: 500 var(--step-0)/1 var(--font-mono); font-variant-numeric: tabular-nums; color: var(--text-hi); }

@property --glow {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

/* El glow del lienzo entra/sale suave al activar una zona (2.40+) */
.device-stage {
  --glow: transparent;
  filter: drop-shadow(0 0 22px var(--glow));
  transition: --glow 280ms var(--ease-out);
}
.device-stage.zona-activa { --glow: var(--accent-glow); }

/* Pop para confirmar aplicación de perfil (transform+opacity, spring, una vez) */
.pop { transition: scale var(--t-base) var(--ease-spring), opacity var(--t-base) var(--ease-out); }
.pop:active { scale: .985; }

/* Reset global de movimiento (patrón web.dev) */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
    scroll-behavior: auto !important;
  }
  .zone[aria-pressed="true"] .fill {
    animation: none;
    filter: drop-shadow(0 0 8px var(--accent-glow));  /* estado visible estático */
  }
}

