// Auditoría WCAG AA de tokens OKLCH — consola del webview o CI
// (WebKitGTK: activa WebKitSettings enable-developer-extras para el inspector)
const Y = (L, C, H) => {
  const a = C * Math.cos(H * Math.PI / 180), b = C * Math.sin(H * Math.PI / 180);
  const [l, m, s] = [
    L + 0.3963377774 * a + 0.2158037573 * b,
    L - 0.1055613458 * a - 0.0638541728 * b,
    L - 0.0894841775 * a - 1.2914855480 * b,
  ].map(x => x ** 3);
  const enc = c => c <= 0.0031308 ? 12.92 * c : 1.055 * c ** (1 / 2.4) - 0.055;
  const [r, g, bl] = [
     4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s,
  ].map(c => enc(Math.min(1, Math.max(0, c))));
  return 0.2126 * r + 0.7152 * g + 0.0722 * bl;
};
const ratio = (c1, c2) => {
  const y1 = Y(...c1), y2 = Y(...c2);
  return (Math.max(y1, y2) + 0.05) / (Math.min(y1, y2) + 0.05);
};
