const DPI_VALUES = [50, 100, 200, 400, 800, 1200, 1600, 3200, 6400, 10000, 16000, 26000];
const slider = document.querySelector(".dpi-slider");
const out = document.querySelector(".dpi-value");
slider.min = 0;
slider.max = DPI_VALUES.length - 1;
slider.step = 1;
slider.value = DPI_VALUES.indexOf(1600);   // etapa por defecto

let lastSent = 0;
function paintDpi() {
  const dpi = DPI_VALUES[+slider.value];
  out.textContent = dpi.toLocaleString("es-ES");            // 16 000 con separador
  slider.setAttribute("aria-valuetext", dpi + " DPI");      // lo que lee el lector
  slider.style.setProperty("--pos", (+slider.value / (DPI_VALUES.length - 1)) * 100 + "%");
  const now = performance.now();
  if (now - lastSent > 40) { lastSent = now; bridgeSend("dpi", { dpi }); }
}
slider.addEventListener("input", paintDpi);
paintDpi();

