const macroEvents = [
  { tipo: "press",   detalle: "KeyW", ms: 40  },
  { tipo: "release", detalle: "KeyW", ms: 80  },
  { tipo: "click",   detalle: "left", ms: 60  },
  { tipo: "delay",   detalle: "",     ms: 250 },
];
const macroList = document.querySelector(".macro");
const macroTotal = document.querySelector(".macro-total");
const MS_MAX = 60000;

function renderMacro() {
  macroList.innerHTML = "";
  macroEvents.forEach((e, i) => {
    const li = document.createElement("li");
    li.className = "macro-row";
    // OJO: si 'detalle' puede venir de fichero importado, escápalo con textContent, como aquí
    li.innerHTML =
      '<span class="ev-idx"></span>' +
      '<span class="ev-tipo"></span>' +
      '<span class="ev-det"></span>' +
      '<input class="ev-ms" type="number" min="0" max="' + MS_MAX + '" step="1" value="' + e.ms + '"' +
      ' aria-label="Duración del evento ' + (i + 1) + ' en milisegundos">' +
      '<span class="ev-actions">' +
      '<button class="ev-up" aria-label="Subir evento ' + (i + 1) + '"' + (i === 0 ? " disabled" : "") + '>↑</button>' +
      '<button class="ev-dn" aria-label="Bajar evento ' + (i + 1) + '"' + (i === macroEvents.length - 1 ? " disabled" : "") + '>↓</button>' +
      '<button class="ev-x" aria-label="Eliminar evento ' + (i + 1) + '">✕</button>' +
      '</span>';
    li.querySelector(".ev-tipo").textContent = e.tipo;
    li.querySelector(".ev-det").textContent = e.detalle || "—";
    li.querySelector(".ev-ms").addEventListener("change", (ev) => {
      macroEvents[i].ms = Math.min(MS_MAX, Math.max(0, Number(ev.target.value) || 0));
      renderMacro();
    });
    li.querySelector(".ev-up").addEventListener("click", () => {
      [macroEvents[i - 1], macroEvents[i]] = [macroEvents[i], macroEvents[i - 1]];
      renderMacro();
    });
    li.querySelector(".ev-dn").addEventListener("click", () => {
      [macroEvents[i + 1], macroEvents[i]] = [macroEvents[i], macroEvents[i + 1]];
      renderMacro();
    });
    li.querySelector(".ev-x").addEventListener("click", () => {
      macroEvents.splice(i, 1);
      renderMacro();
    });
    macroList.append(li);
  });
  macroTotal.textContent = "total " + macroEvents.reduce((a, e) => a + e.ms, 0) + " ms";
}
renderMacro();
