// HTML: <div class="toast-region" role="region" aria-label="Avisos"></div>
// HTML: <button class="action"><span class="label">Aplicar</span><span class="spin" hidden></span></button>
const toastRegion = document.querySelector(".toast-region");
function toast(msg, kind = "ok", ms = 3200) {
  const t = document.createElement("div");
  t.className = "toast";
  t.dataset.kind = kind;
  t.setAttribute("role", kind === "err" ? "alert" : "status");  // alert interrumpe; status no
  const dot = document.createElement("span"); dot.className = "toast-dot";
  const txt = document.createElement("span"); txt.textContent = msg;
  t.append(dot, txt);
  toastRegion.append(t);
  while (toastRegion.children.length > 3) toastRegion.firstChild.remove();
  setTimeout(() => {
    t.classList.add("leaving");
    t.addEventListener("animationend", () => t.remove(), { once: true });
  }, ms);
}

const saveBtn = document.querySelector(".action");
const label = saveBtn.querySelector(".label");
const origLabel = label.textContent;
let busy = false;

async function applyConfig() {
  if (busy) return;
  busy = true;
  saveBtn.dataset.state = "saving";
  saveBtn.setAttribute("aria-busy", "true");
  saveBtn.querySelector(".spin").hidden = false;
  label.textContent = "Aplicando…";
  try {
    bridgeSend("apply-profile", dumpConfig());   // ver snippet del puente
    await configApplied();                        // promesa resuelta por el daemon vía bridge
    label.textContent = origLabel;
    saveBtn.classList.add("flash-ok");
    saveBtn.addEventListener("animationend", () => saveBtn.classList.remove("flash-ok"), { once: true });
  } catch (err) {
    label.textContent = origLabel;
    toast("No se pudo aplicar el perfil", "err");   // el fallo SÍ lleva toast
  } finally {
    saveBtn.dataset.state = "idle";
    saveBtn.removeAttribute("aria-busy");
    saveBtn.querySelector(".spin").hidden = true;
    busy = false;
  }
}
saveBtn.addEventListener("click", applyConfig);
// configApplied(): const p = new Promise(...); el bridge la resuelve cuando GTK emite la respuesta.
