// JS (dentro del webview) — cada handler se registra en el UserContentManager:
const bridgeSend = (handler, payload) => {
  const mh = window.webkit?.messageHandlers;
  if (mh && mh[handler]) {
    mh[handler].postMessage(JSON.stringify(payload));   // JSON explícito: inmune al binding
  } else {
    console.debug("[rat9 sin bridge]", handler, payload); // útil probando en Firefox/Chrome
  }
};
